To convert Markdown formatted text to HTML, you can use a library like `cpp-md-parser` or `commonmark`. Here's an example using `cpp-md-parser` and `pugixml` for HTML generation. Make sure to install these libraries using package manager or build from source before using the code below.

1. First, install `cpp-md-parser` and `pugixml`:
   - For Ubuntu: `sudo apt-get install libcpp-md-parser-dev libpugixml-dev`
   - For macOS: `brew install cpp-md-parser pugixml`

2. Create a new C++ file (e.g., `markdown_to_html.cpp`) and add the following code:

```cpp
#include <iostream>
#include <string>
#include <memory>
#include <pugixml.hpp>
#include <cppmark/parser.h>

std::string markdown_to_html(const std::string& markdown) {
    using namespace cppmark;
    using namespace std;

    // Initialize parser
    auto parser = make_shared<Parser>();

    // Parse markdown
    auto document = parser->parse(markdown.c_str(), markdown.c_str() + markdown.size(), nullptr);

    // Create HTML document
    pugi::xml_document html_doc;
    pugi::xml_node root = html_doc.append_child(pugi::node_declaration("html", "xmlns:md='http://commonmark.org/schema/'"));
    root.append_child(pugi::node_declaration("head", nullptr));
    root.append_child(pugi::node_declaration("body", nullptr));

    // Convert nodes to HTML
    convert_node_to_html(document.get(), root, parser.get());

    // Get HTML as a string
    stringstream ss;
    html_doc.save(ss, 4);

    return ss.str();
}

void convert_node_to_html(const NodePtr& node, pugi::xml_node& parent, Parser* parser) {
    if (node == nullptr) {
        return;
    }

    string node_type = node->type_name();

    if (node_type == "text") {
        auto text_node = static_cast<TextNode*>(node.get());
        pugi::xml_node html_node = parent.append_child(pugi::node_declaration("span", "md:" + node->as_string().substr(1)));
        html_node.append_child(pugi::node_pcdata(text_node->text().c_str(), text_node->text().size()));
    } else if (node_type == "heading") {
        auto heading_node = static_cast<HeadingNode*>(node.get());
        pugi::xml_node html_node = parent.append_child(pugi::node_declaration("h" + to_string(heading_node->level), "class='heading'"));
        convert_node_to_html(heading_node->content, html_node, parser);
    } else if (node_type == "paragraph") {
        auto paragraph_node = static_cast<ParagraphNode*>(node.get());
        pugi::xml_node html_node = parent.append_child(pugi::node_declaration("p", nullptr));
        convert_node_to_html(paragraph_node->content, html_node, parser);
    } else if (node_type == "inline_code") {
        auto inline_code_node = static_cast<InlineCodeNode*>(node.get());
        pugi::xml_node html_node = parent.append_child(pugi::node_declaration("code", "class='inline-code'"));
        html_node.append_child(pugi::node_pcdata(inline_code_node->text().c_str(), inline_code_node->text().size()));
    } else if (node_type == "code_block") {
        auto code_block_node = static_cast<CodeBlockNode*>(node.get());
        pugi::xml_node html_node = parent.append_child(pugi::node_declaration("pre", "class='code-block'"));
        pugi::xml_node code_node = html_node.append_child(pugi::node_declaration("code", "class='code'"));
        code_node.append_child(pugi::node_pcdata(code_block_node->info.lang.c_str(), code_block_node->info.lang.size()));
        pugi::xml_node content_node = code_node.append_child(pugi::node_declaration("pre", nullptr));
        for (auto& line : code_block_node->content) {
            content_node.append_child(pugi::node_pcdata(line.text.c_str(), line.text.size()));
        }
    }

    // Recursively process children
    for (auto& child : node->children) {
        convert_node_to_html(child, parent, parser);
    }
